app std-tactics-board-3d "1.0.0"
"3D player-controlled grid-tactics board FRAME: composes grid-tactics (units authority) + fx-particles + round-flow + a player-intent/render trait onto one shared GameState. Games consume this molecule and supply only theme/assets/units via config."
orbital TacticsBoard3DOrbital {
  type SceneLight = {
    intensity : number
    color : string
    position : [number]
  }
  type SceneHemiLight = {
    intensity : number
    color : string
    groundColor : string
  }
  type ScenePointLight = {
    intensity : number
    color : string
    position : [number]!
    distance : number
    decay : number
  }
  type Lighting3D = {
    ambient : SceneLight
    directional : SceneLight
    hemisphere : SceneHemiLight
    points : [ScenePointLight]
    environment : "room" | "none"
    toneMapping : "aces" | "none"
  }
  type Post3D = {
    bloom : { intensity : number  threshold : number  smoothing : number }
    vignette : { offset : number  darkness : number }
  }

  uses Tactics from "std/behaviors/std-grid-tactics"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Round from "std/behaviors/std-round-flow"
  uses MeshArt from "std/behaviors/std-mesh-asset-art"

  type Asset = {
    url : asset
    atlas : asset
    sprite : string
    role : string
    category : string
    animations : [string]
    style : string
    dimension : string
    aspect : string
    name : string
    thumbnailUrl : string
  }
  type Unit = {
    id : string!
    position : { x : number!  y : number! }
    x : number
    y : number
    z : number
    team : string
    health : number
    maxHealth : number
    unitType : string
    name : string
    modelUrl : Asset
    yaw : number
  }
  type Tile = {
    id : string
    x : number!
    y : number!
    z : number
    terrain : string
    passable : boolean
    modelUrl : Asset
  }
  type Fx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
  }
  type FxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    gravity : number
    vx : number
    vy : number
    vz : number
    space : string
    effect : string
    particleCount : number
  }
  type ValidMove = { x : number!  z : number! }
  type Feature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string
    assetUrl : Asset
    color : string
    elevation : number
  }
  type AssetManifest = {
    terrains : Map string Asset
    units : Map string Asset
    features : Map string Asset
    effects : Map string Asset
  }

  entity GameState [runtime, shared] {
    id : string!
